(* [comment removed for export] *)
Definition meta_index (p x : Z) : option Z :=
  if (p + 24 <=? x) && (x <? p + 24 + 40 * 101) && ((x - (p + 24)) mod 40 =? 0)
  then Some ((x - (p + 24)) / 40) else None.

